import { createAction, createAsyncThunk } from '@reduxjs/toolkit';
import { noop } from '@proton/shared/lib/helpers/function';
import isDeepEqual from '@proton/shared/lib/helpers/isDeepEqual';
import {
    ESResults,
    EventUpdates,
    NewStateParams,
    OptimisticDelete,
    OptimisticUpdates,
    QueryParams,
    QueryResults,
    RetryData,
} from './elementsTypes';
import { Element } from '../../models/element';
import { ELEMENTS_LIST_LOAD_RETRY_DELAY, ELEMENTS_LIST_STALE_RETRY_DELAY } from '../../../constants';
import { getQueryElementsParameters, queryElement, queryElements } from './helpers/elementQuery';
import { RootState } from '../store';

export const reset = createAction<NewStateParams>('elements/reset');

export const updatePage = createAction<number>('elements/updatePage');

export const retry = createAction<RetryData>('elements/retry');

export const retryStale = createAction<{ queryParameters: any }>('elements/retryStale');

export const holdRequest = createAction<QueryParams>('elements/holdRequest');

export const backendActionStarted = createAction<void>('elements/backendActionStarted');

export const backendActionFinished = createAction<void>('elements/backendActionFinished');

export const load = createAsyncThunk<QueryResults, QueryParams>(
    'elements/load',
    async (queryParams: QueryParams, { getState, dispatch }) => {
        const queryParameters = getQueryElementsParameters(queryParams);

        const query = () =>
            queryElements(queryParams.api, queryParams.abortController, queryParams.conversationMode, queryParameters);

        // Issue the request again after a fixed delay, unless backend actions modifying
        // the list are in progress: the request is then held back until the last of them
        // settles. It is dropped if the parameters of the list changed in the meantime,
        // the view takes care of requesting up to date data in that case
        const scheduleNewRequest = () => {
            setTimeout(() => {
                const state = (getState() as RootState).elements;
                if (!isRequestUpToDate(queryParameters, state)) {
                    return;
                }
                if (state.pendingActions > 0) {
                    dispatch(holdRequest(queryParams));
                } else {
                    void dispatch(load(queryParams));
                }
            }, ELEMENTS_LIST_LOAD_RETRY_DELAY);
        };

        let results: QueryResults;
        try {
            results = await query();
        } catch (error: any | undefined) {
            // Wait a couple of seconds before trying again
            scheduleNewRequest();
            throw error;
        }

        // A stale response must not be committed: the same query is issued again after a second
        while (results.Stale === 1) {
            dispatch(retryStale({ queryParameters }));

            await new Promise<void>((resolve) => {
                setTimeout(resolve, ELEMENTS_LIST_STALE_RETRY_DELAY);
            });

            const state = (getState() as RootState).elements;
            if (!isRequestUpToDate(queryParameters, state)) {
                throw new Error('Stale elements list request dropped');
            }
            if (state.pendingActions > 0) {
                // Backend actions modifying the list are in progress: hold the request back,
                // it will be issued once the last of them settles
                dispatch(holdRequest(queryParams));
                throw new Error('Elements list request on hold');
            }

            try {
                results = await query();
            } catch (error: any | undefined) {
                scheduleNewRequest();
                throw error;
            }
        }

        return results;
    }
);
